CREATE TRIGGER IF NOT EXISTS bp26_headline_heavy_tick AFTER INSERT ON fleet_tick_heavy
BEGIN
  UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED',
      last_value = CAST((SELECT COUNT(*) FROM metric_registry r WHERE r.source_of_truth LIKE '%[BP26]%' AND r.metric NOT IN ('bp26_metrics_unmeasured', 'bp26_issues_open')
                          AND (r.last_value IS NULL OR trim(r.last_value) = '' OR trim(r.last_value) GLOB '*[^0-9.+-]*')) AS TEXT)
    WHERE metric = 'bp26_metrics_unmeasured' AND (last_refreshed IS NULL OR last_refreshed < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED',
      last_value = CAST((SELECT COUNT(*) FROM agent_issues WHERE predicate_id LIKE 'BP26-%' AND status = 'open') AS TEXT)
    WHERE metric = 'bp26_issues_open' AND (last_refreshed IS NULL OR last_refreshed < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
END;

