INSERT OR IGNORE INTO human_actions (slug, title, why, default_in_effect, action, sev, status, source) VALUES ('bp26-email-agent-ai-disclosure', 'Decide whether the email agent''s replies in your name carry an AI disclosure (EU AI Act Art. 50(1))', 'IDENTITY-BOUND: the email agent answers mail as you, from your mailbox and in your name (owner directive 2026-10-12: replies in your own voice). EU AI Act Art. 50(1), applicable since 2026-08-02, requires that people are told when they interact with an AI system unless it is obvious; replies that read as human-written are the case it targets. Whether the purely-personal-use exclusion covers your mail is a legal judgment this fleet cannot make for you. Recommendation: add a one-line notice to agent-written replies (for example: ''Drafted with AI assistance on behalf of Rowan'').', 'No change: agent replies continue without a disclosure until you decide. Reply ''disclose'' to add the one-line notice or ''keep'' to leave replies as they are.', 'Reply to this card with ''disclose'' or ''keep''.', 'high', 'open', 'bp26-catalogue');

INSERT OR IGNORE INTO human_actions (slug, title, why, default_in_effect, action, sev, status, source) VALUES ('bp26-social-bot-labels', 'Turn on the automated-account labels for the accounts the fleet posts to (X, Bluesky, Mastodon)', 'IDENTITY-BOUND: the labels are settings on your own accounts (X: Automated label linked to a managing account; Bluesky: Settings > Account > Automation label; Mastodon: ''This is an automated account''). X''s developer guidelines require the label for automated accounts; Bluesky and Mastodon offer it. q08 forecasts post to your personal Bluesky account, so the label would mark that personal account as automated: that is your choice to make.', 'Posts continue. The fleet adds a short automation marker to the text of each automated post (BP26-SOCIAL-AUTOMATION-1), which needs no account setting.', 'Set the labels in each account''s settings, or reply ''not on personal accounts'' to keep only the in-text marker.', 'normal', 'open', 'bp26-catalogue');

INSERT OR IGNORE INTO human_actions (slug, title, why, default_in_effect, action, sev, status, source) VALUES ('bp26-crossref-membership', 'Decide whether QNFO joins Crossref (about USD 200 a year plus per-record fees) to give papers DOIs', 'IDENTITY-BOUND: money and a membership agreement in your name. Crossref''s lowest tier is USD 200 a year for organisations with publishing revenue or expenses up to USD 1,000, posted content costs USD 0.25 per record (USD 0.20 from January 2027), and members must register DOIs for all published content. Whether a sole-trader QNFO qualifies as a member organisation is for Crossref to confirm.', 'No DOIs. Papers keep immutable versioned URLs, content hashes, CITATION.cff and OAI-PMH as their identifiers (BP26-PAPER-PIDS-1).', 'Reply ''join'' to start the membership, or ''no DOIs'' to keep the default.', 'normal', 'open', 'bp26-catalogue');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome) SELECT 'claude-session-bp26', 'EU AI Act Art. 50(4) exempts AI-generated public-interest text only under human review or editorial control; the owner''s directive is no manual approval steps.', 'Kept full automation and labelled every AI-generated piece instead of adding a sampled human review (DECISION-AUTOPROCEED-1 recommended option); shipped PRs 4394, 4396, 4397 and the q08 method note.', 'research report wf-232b4527-680f-8492-8dc9-5ab6ae365e14 (2026-10-26); Code of Practice 2026-06-10; Regulation (EU) 2026/1744 left Article 50 unchanged.', 'labels live on q08.org, reading.q08.org and ipatent after the PRs deploy', 'q08.org, reading.q08.org, ipatent.qnfo.org public pages', 'revert the three PRs; or add a sampled owner review and drop the label where the exemption then applies', 'BP26 catalogue programmed', 'ai_label_coverage reaches 1.0 once papers.qnfo.org, qnfo.org and social posts carry the label' WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.actor = 'claude-session-bp26' AND d.action = 'Kept full automation and labelled every AI-generated piece instead of adding a sampled human review (DECISION-AUTOPROCEED-1 recommended option); shipped PRs 4394, 4396, 4397 and the q08 method note.');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome) SELECT 'claude-session-bp26', 'Every finding of the catalogue must become tracked work with a doer, a metric and a closing probe (owner directive 2026-10-26).', 'Programmed 30 practices as BP26-* agent_issues under five projects of the existing programs, 56 metrics with triggers, two headline metrics and goal BP26-CATALOGUE.', 'migrations/2026-10-26-best-practice-catalogue.sql', 'bp26_issues_open starts at 30 and falls as practices ship; bp26_metrics_unmeasured starts at 56', 'qnfo-audit agent_issues, metric_registry, analytics_metric_triggers, projects, goals, roadmap_implementation, human_actions', 'the Rollback line of the migration (issues are closed with evidence, never deleted)', 'BP26 catalogue programmed', 'bp26_issues_open < 30 within 7 days' WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.actor = 'claude-session-bp26' AND d.action = 'Programmed 30 practices as BP26-* agent_issues under five projects of the existing programs, 56 metrics with triggers, two headline metrics and goal BP26-CATALOGUE.');
